1314:   const sessionEnd = endSession(currentSig, sessionState, now + encounterCount * 5000);
1315: 
1316:   // Save progress to disk (Significator + WorldState)
1317:   saveGame(sessionEnd.sig);
1318:   saveWorldState(currentWorld);
1319:   if (!JSON_MODE) info('save', `${chalk.green('Progress saved')}`);
1320: 
1321:   banner('SESSION END');
1322: 
1323:   // Session closure narrative
1324:   if (!JSON_MODE) {
1325:     // passedCount tracked directly from encResult.passed during the loop
1326:     const failedCount = completedCount - passedCount;
1327:     const shadowsSurfaced = sessionEnd.summary.shadowsSurfaced;
1328:     const altShifts = history.filter(r => r.altitudeShift !== null).length;
1329: 
1330:     // Rich thematic closure that references what happened
1331:     const linesAdvanced = history.filter(r => r.altitudeShift !== null).map(r => r.altitudeShift!.line);
1332:     const uniqueLinesAdvanced = [...new Set(linesAdvanced)];
1333:     const shadowsByQuadrant: Record<string, number> = {};
1334:     for (const r of history) {
1335:       if (r.shadowSurfaced) {
1336:         shadowsByQuadrant[r.shadowSurfaced] = (shadowsByQuadrant[r.shadowSurfaced] ?? 0) + 1;
1337:       }
1338:     }
1339:     const shadowDetail = Object.entries(shadowsByQuadrant).map(([q, n]) => `${n}×${q}`).join(', ');
1340: 
1341:     const openingLine = passedCount > failedCount
1342:       ? `${chalk.green('This session favored integration.')} ${passedCount}/${completedCount} encounters met their developmental threshold.`
1343:       : `${chalk.yellow('This session was heavy with unfinished catalyst.')} ${failedCount}/${completedCount} encounters remain un-integrated.`;
1344: 
1345:     const altLine = uniqueLinesAdvanced.length > 0
1346:       ? `  ${chalk.magenta('⚡ Lines advanced: ' + uniqueLinesAdvanced.join(', '))}`
1347:       : '';
1348: 
1349:     const shadowLine = shadowDetail
1350:       ? `  ${chalk.red('⚠ Shadows surfaced: ' + shadowDetail)}`
1351:       : `  ${chalk.green('✓ No shadows surfaced this session')}`;
1352: 
1353:     // NPC relationship summary
1354:     const holonDeltas = history.flatMap(r => r.holonDeltas ?? []);
1355:     const relChanges = holonDeltas.filter(d => d.field === 'relationshipStrength');
1356:     const relLine = relChanges.length > 0
1357:       ? `  ${chalk.dim('NPC relationships shifted: ' + relChanges.length + ' encounter' + (relChanges.length > 1 ? 's' : '') + ' with bond changes')}`
1358:       : '';
1359: 
1360:     console.log(`\n  ${chalk.bold('Session Closure')}`);
1361:     console.log(`  ${openingLine}`);
1362:     if (altLine) console.log(altLine);
1363:     console.log(shadowLine);
1364:     if (relLine) console.log(relLine);
1365:     console.log(`\n  ${chalk.dim('The session closes. Each encounter was a mirror — reflecting not who you are, but who you are becoming.')}`);
1366:   }
1367: 
1368:   info('encounters completed', String(completedCount));
1369:   info('total encounters', String(currentSig.totalEncounters));
1370:   info('total sessions', String(sessionEnd.sig.totalSessions));
1371: 
1372:   // Show developmental trajectory (compute fresh CCI from final Significator state)
1373:   console.log('');
