1489: // ── Ollama auto-detect ──────────────────────────────────────────
1490: async function detectOllama(): Promise<{ running: boolean; models: string[] }> {
1491:   try {
1492:     const controller = new AbortController();
1493:     const timeout = setTimeout(() => controller.abort(), 3000);
1494:     const res = await fetch('http://localhost:11434/api/tags', { signal: controller.signal });
1495:     clearTimeout(timeout);
1496:     if (!res.ok) return { running: false, models: [] };
1497:     const data = (await res.json()) as { models?: { name: string }[] };
1498:     const models = (data.models ?? []).map(m => m.name.split(':')[0] ?? m.name);
1499:     return { running: true, models: [...new Set(models)] };
1500:   } catch {
1501:     return { running: false, models: [] };
1502:   }
1503: }
