1505: // ── API key verification ────────────────────────────────────────
1506: async function verifyProviderConnection(provider: ProviderInfo, apiKeyVal: string, modelVal: string, baseUrlVal: string): Promise<{ ok: boolean; message: string }> {
1507:   try {
1508:     const controller = new AbortController();
1509:     const timeout = setTimeout(() => controller.abort(), 10_000);
1510: 
1511:     if (provider.id === 'ollama') {
1512:       // Ollama: GET /api/tags
1513:       const res = await fetch('http://localhost:11434/api/tags', { signal: controller.signal });
1514:       clearTimeout(timeout);
1515:       if (res.ok) return { ok: true, message: 'Ollama connected' };
1516:       return { ok: false, message: `Ollama responded with ${res.status}` };
1517:     }
1518: 
1519:     if (provider.id === 'anthropic') {
1520:       // Anthropic: POST /v1/messages with minimal payload
1521:       const res = await fetch(`${baseUrlVal}/messages`, {
1522:         method: 'POST',
1523:         headers: {
1524:           'Content-Type': 'application/json',
1525:           'x-api-key': apiKeyVal,
1526:           'anthropic-version': '2023-06-01',
1527:         },
1528:         body: JSON.stringify({
1529:           model: modelVal,
1530:           messages: [{ role: 'user', content: 'ping' }],
1531:           max_tokens: 1,
1532:         }),
1533:         signal: controller.signal,
1534:       });
1535:       clearTimeout(timeout);
1536:       if (res.ok) return { ok: true, message: 'Anthropic connected' };
1537:       if (res.status === 401 || res.status === 403) return { ok: false, message: 'Invalid API key' };
1538:       return { ok: false, message: `Anthropic responded with ${res.status}` };
1539:     }
1540: 
1541:     // OpenAI / Gemini / Custom: GET /models
1542:     const res = await fetch(`${baseUrlVal}/models`, {
1543:       headers: { 'Authorization': `Bearer ${apiKeyVal}` },
1544:       signal: controller.signal,
1545:     });
1546:     clearTimeout(timeout);
1547:     if (res.ok) return { ok: true, message: 'Connected' };
1548:     if (res.status === 401 || res.status === 403) return { ok: false, message: 'Invalid API key' };
1549:     return { ok: false, message: `Endpoint responded with ${res.status}` };
1550:   } catch (err: any) {
1551:     return { ok: false, message: err.name === 'AbortError' ? 'Connection timed out' : 'Connection failed' };
1552:   }
1553: }
