718:   /**
719:    * Module-aware fallback: uses the assessment module's tasks, drive probes,
720:    * and scoring rubric to present a real developmental assessment even without the LLM.
721:    * Selects a task matching the encounter modality, presents it as a narrative challenge,
722:    * evaluates the response against drive probes, detects shadow patterns,
723:    * and computes altitude progression.
724:    */
725:   private async runModuleAssessment(_line: Line, stage: Stage, now: number): Promise<OrchestratorResult> {
726:     const module = this.module!;
727:     const holon = this.world.holons.find(h => h.id === this.encounter.holonSource);
728:     const holonName = holon?.name ?? 'A presence';
729:     const currentModality = this.encounter.modality;
730: 
731:     // 1. Select the best task from the module based on modality
732:     const task = this.selectTaskForModality(module, currentModality);
733:     // Track the actual presented task for narrative building (fix B.2)
734:     this._currentPresentedTask = task;
735: 
736:     // 2. Present the task as a narrative challenge via uiHandler
737:     const askResult = await this.presentModuleTask(module, task, currentModality, holonName);
738:     const answer = askResult.answers[0];
739:     const rawLabel = answer?.selectedLabels[0] ?? '';
740:     const writeIn = answer?.writeInValue;
741:     const playerResponseText = writeIn ?? rawLabel;
742: 
743:     // 3. Evaluate using the TaskRenderer's evaluate() if available (produces TrialResult with timing/accuracy)
744:     //    Fall back to drive-probe evaluation if no renderer evaluate is available
745:     const endTimeMs = Date.now();
746:     let evaluation: {
747:       passed: boolean;
748:       polarityDirection: 'sto' | 'sts' | 'neutral';
749:       driveScores: { agency: number; communion: number; eros: number; agape: number };
750:       driveSignals: { agency: string; communion: string; eros: string; agape: string };
751:       feedback: string;
752:     };
753:     let trialResult: TrialResult | null = null;
754: 
755:     if (this._currentRendererEvaluate) {
756:       // Use the TaskRenderer's evaluate function for real scoring
757:       trialResult = this._currentRendererEvaluate(playerResponseText, this._currentTaskStartTime, endTimeMs);
758: 
759:       // Extract drive metadata from the trial's rawResponse (set by TaskRenderers)
760:       const rawResp = trialResult?.rawResponse as any;
761:       const matchedDrive: string | null = rawResp?.matchedDrive ?? null;
762:       const matchedPolarity: string = rawResp?.matchedPolarity ?? 'neutral';
763:       const correctnessScore: number = rawResp?.correctnessScore ?? 0.5;
764: 
765:       // Use correctnessScore as the primary scoring signal (from TaskRenderer options)
766:       const baseScore = Math.min(1, Math.max(0, correctnessScore));
767: 
768:       // D.9: Use shared shadow keyword detection helper (DRY)
769:       let writeInDriveDetection: { drive: string; polarity: string; shadowKeyword: string | null } | null = null;
770:       if (writeIn) {
771:         writeInDriveDetection = AgenticOrchestrator.detectWriteInShadow(writeIn);
772:       }
773: 
774:       // When a write-in is present, its keyword-based detection takes priority over
775:       // the renderer's label matching (which can false-positive on short words like 'I').
776:       const effectiveDrive = writeInDriveDetection?.drive ?? matchedDrive ?? null;
777:       const effectivePolarity = writeInDriveDetection?.polarity ?? (matchedPolarity !== 'neutral' ? matchedPolarity : 'neutral');
778: 
779:       // Build differentiated drive scores:
780:       // - The matched/driven drive gets the full baseScore (or boosted for write-in depth)
781:       // - Other drives get baseline neutral (0.5)
782:       // - For write-ins with no shadow detection, apply a depth boost and distribute evenly
783:       const isWriteInWithNoShadow = matchedDrive === null && !writeInDriveDetection && !!writeIn;
784: 
785:       // ── SCORING FIX: Use rubric dimension weights on TrialResult dimensions ──
786:       // OLD: averaged 4 drives → compressed to ~0.55 always, even correct answers failed at threshold 0.6
787:       // NEW: compute weighted score from TrialResult dimensions using the module's rubric weights.
788:       // This gives a true performance signal: correct MCQ → ~0.8, partial → ~0.55, wrong → ~0.25.
789:       const rubricWeights = module.scoringRubric.dimensionWeights;
790:       const trialDims = trialResult!.dimensions;
791:       let weightedSum = 0;
792:       let totalWeight = 0;
793:       for (const [dim, weight] of Object.entries(rubricWeights)) {
794:         const val = trialDims[dim as keyof typeof trialDims];
795:         if (weight && typeof val === 'number') {
796:           weightedSum += val * weight;
797:           totalWeight += weight;
798:         }
799:       }
800:       // Blend the rubric-weighted score with the drive-correctness score for a robust signal
801:       const rubricScore = totalWeight > 0 ? weightedSum / totalWeight : baseScore;
802:       const blendedScore = rubricScore * 0.6 + baseScore * 0.4;
803: 
804:       // Drive scores: matched drive gets blendedScore (consistent with pass/fail),
805:       // write-in depth bonus applied on top. Unmatched drives get a lower baseline.
806:       const matchedScore = isWriteInWithNoShadow ? Math.max(blendedScore, 0.55) : blendedScore;
807:       const driveScores = {
808:         agency: effectiveDrive === 'agency' ? matchedScore
809:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
810:           : matchedScore,
811:         communion: effectiveDrive === 'communion' ? matchedScore
812:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
813:           : matchedScore,
814:         eros: effectiveDrive === 'eros' ? matchedScore
815:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
816:           : matchedScore,
817:         agape: effectiveDrive === 'agape' ? matchedScore
818:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
819:           : matchedScore,
820:       };
821: 
822:       // Determine polarity from the effective drive detection
823:       const polarityDirection = effectivePolarity === 'sts' ? 'sts' as const
824:         : effectivePolarity === 'sto' ? 'sto' as const
825:         : 'neutral' as const;
826: 
827:       // Derive drive signals from the expression pattern.
828:       // IMPORTANT: Shadow signals ONLY come from write-in keyword detection or forceShadow.
829:       // A wrong MCQ answer (low correctnessScore) is a performance miss, NOT a shadow expression.
830:       const shadowFromWriteIn = writeInDriveDetection?.shadowKeyword ?? null;
831:       const driveSignals = {
832:         agency: effectiveDrive === 'agency'
833:           ? (shadowFromWriteIn === 'DarkAddicted' ? 'DarkAddicted' : 'HealthyBalanced')
834:           : 'HealthyBalanced',
835:         communion: effectiveDrive === 'communion'
836:           ? (shadowFromWriteIn === 'DarkAverted' ? 'DarkAverted' : 'HealthyBalanced')
837:           : 'HealthyBalanced',
838:         eros: effectiveDrive === 'eros'
839:           ? (shadowFromWriteIn === 'GoldenAddicted' ? 'GoldenAddicted' : 'HealthyBalanced')
840:           : 'HealthyBalanced',
841:         agape: effectiveDrive === 'agape'
842:           ? (shadowFromWriteIn === 'GoldenAverted' ? 'GoldenAverted' : 'HealthyBalanced')
843:           : 'HealthyBalanced',
844:       };
845: 
846:       // Determine pass: blendedScore must meet threshold AND no shadow pathology
847:       const passThreshold = module.scoringRubric.passThreshold ?? 0.5;
848:       const effectiveScore = isWriteInWithNoShadow ? Math.max(blendedScore, 0.55) : blendedScore;
849:       const hasShadow = !!shadowFromWriteIn;
850:       const passed = !hasShadow && effectiveScore >= passThreshold;
851: 
852:       // Build contextual developmental feedback based on score, drive, polarity, and history
853:       const driveLabel = effectiveDrive ?? 'unidentified';
854:       const polarityLabel = effectivePolarity === 'sts' ? 'self-oriented' : effectivePolarity === 'sto' ? 'other-oriented' : 'balanced';
855:       const scorePct = (baseScore * 100).toFixed(0);
856:       const historyCount = this.history.length;
857:       const recentPasses = this.history.slice(-3).filter(r => Object.values(r.polarityTrace.driveDirectionality).every(d => d === 'HealthyBalanced')).length;
858:       const consistencyNote = recentPasses >= 3 ? ' You are building strong momentum across encounters.'
859:         : recentPasses === 0 && historyCount >= 2 ? ' The last few encounters have been challenging — this is where real growth happens.'
860:         : '';
