984:           finalSig = { ...finalSig, currentStage: nextStage };
985:         }
986:       }
987:     }
988: 
989:     // PESTLE accumulation
990:     const PESTLE_DIMS_ARRAY: (keyof PESTLETension)[] = ['political', 'economic', 'social', 'technological', 'legal', 'environmental'];
991:     const dim = PESTLE_DIMS_ARRAY[Math.floor(Math.random() * PESTLE_DIMS_ARRAY.length)]!;
992:     const newTension = accumulateTension(
993:       (updated.world as any).pestleTension ?? { political: 0, economic: 0, social: 0, technological: 0, legal: 0, environmental: 0 },
994:       dim,
995:       0.05,
996:     );
997:     const activeEvents = (updated.world as any).activeMacroEvents ?? [];
998:     const macroEvent = tryTriggerMacroEvent(newTension, activeEvents, finalSig.currentStage, now);
999:     const newActiveEvents = macroEvent ? [...activeEvents, macroEvent] : activeEvents;
1000:     const updatedWorld = { ...updated.world, pestleTension: newTension, activeMacroEvents: newActiveEvents } as WorldState;
1001: 
1002:     return {
1003:       updatedSig: finalSig,
1004:       updatedWorld,
1005:       finalResult,
1006:       consequenceRecord: updatedRecord,
1007:       narrativeSummary,
1008:       feedback: evaluation.feedback,
1009:       messages: this.messages,
1010:     };
1011:   }
