1013:   /**
1014:    * Select the best assessment task from the module based on encounter modality.
1015:    */
1016:   private selectTaskForModality(module: StageAssessment, modality: Modality): AssessmentTask {
1017:     // Preferred task types for each modality, with fallback chains
1018:     // If the preferred types aren't available in the module, we try broader types
1019:     const modalityFallbackChain: Record<string, readonly TaskType[]> = {
1020:       Deterministic: ['n_back', 'stroop', 'go_no_go', 'hold', 'reaction_time', 'rhythm'],
1021:       LanguageReflective: ['llm_dialogue', 'self_report', 'emotion_identification', 'scenario'],
1022:       ScenarioChoice: ['dilemma', 'scenario', 'emotion_identification', 'self_report'],
1023:       Embodied: ['hold', 'rhythm', 'imitation', 'reaction_time', 'go_no_go'],
1024:       Strategic: ['pattern_prediction', 'value_ranking', 'n_back', 'stroop'],
1025:       SocialCooperative: ['cooperation', 'dilemma', 'emotion_identification', 'scenario', 'self_report'],
1026:       ImmersiveRPG: ['scenario', 'dilemma', 'llm_dialogue', 'emotion_identification', 'self_report'],
1027:     };
1028: 
1029:     const chain = modalityFallbackChain[modality] ?? ['n_back', 'scenario', 'self_report'];
1030: 
1031:     // Walk the fallback chain: first match wins
1032:     for (const prefType of chain) {
1033:       const match = module.tasks.find(t => t.type === prefType);
1034:       if (match) return match;
1035:     }
1036: 
1037:     // CRITICAL FIX: When no task type matches the modality's preference chain,
1038:     // generate a modality-appropriate generic task instead of falling to tasks[0].
1039:     // This prevents Cognitive modules (which have only n_back/pattern/go_nogo) from
1040:     // showing n-back when ScenarioChoice modality is requested.
1041:     return this.generateModalityFallbackTask(modality, module);
1042:   }
