1044:   /**
1045:    * Generate a generic task appropriate for the modality when the module
1046:    * doesn't have any of the preferred task types. This ensures ScenarioChoice
1047:    * always shows a dilemma, ImmersiveRPG always shows a scenario, etc.
1048:    */
1049:   private generateModalityFallbackTask(modality: Modality, module: StageAssessment): AssessmentTask {
1050:     const prefix = `${module.line.toLowerCase()}-${module.stage.toLowerCase()}`;
1051:     // Inject stage into all generated task parameters so TaskRenderers can use it for difficulty scaling
1052:     const stage = module.stage;
1053:     switch (modality) {
1054:       case 'ScenarioChoice':
1055:       case 'ImmersiveRPG':
1056:         return {
1057:           id: `generic-dilemma-${prefix}`,
1058:           type: 'dilemma',
1059:           description: `A developmental dilemma at the ${module.stage} stage of ${module.line} development`,
1060:           parameters: { dilemmaType: 'developmental', choices: 4, stage, line: module.line },
1061:           measures: ['depth', 'coherence'],
1062:         };
1063:       case 'LanguageReflective':
1064:         return {
1065:           id: `generic-self-report-${prefix}`,
1066:           type: 'self_report',
1067:           description: `Self-inquiry reflection at the ${module.stage} stage of ${module.line} development`,
1068:           parameters: { stage },
1069:           measures: ['depth', 'metacognition'],
1070:         };
1071:       case 'SocialCooperative':
1072:         return {
1073:           id: `generic-cooperation-${prefix}`,
1074:           type: 'cooperation',
1075:           description: `Cooperative dynamics at the ${module.stage} stage of ${module.line} development`,
1076:           parameters: { stage },
1077:           measures: ['depth', 'coherence'],
1078:         };
1079:       case 'Embodied':
1080:         return {
1081:           id: `generic-hold-${prefix}`,
1082:           type: 'hold',
1083:           description: `Attentional hold at the ${module.stage} stage of ${module.line} development`,
1084:           parameters: { items: 3, holdDurationMs: 5000, stage },
1085:           measures: ['accuracy', 'consistency'],
1086:         };
1087:       case 'Strategic':
1088:         return {
1089:           id: `generic-pattern-${prefix}`,
1090:           type: 'pattern_prediction',
1091:           description: `Pattern recognition at the ${module.stage} stage of ${module.line} development`,
1092:           parameters: { disks: 3, attempts: 4, stage },
1093:           measures: ['accuracy', 'complexity_handled'],
1094:         };
1095:       case 'Deterministic':
1096:       default:
1097:         return module.tasks[0] ?? {
1098:           id: `generic-nback-${prefix}`,
1099:           type: 'n_back',
1100:           description: `Working memory challenge at the ${module.stage} stage of ${module.line} development`,
1101:           parameters: { n: 2, trials: 12, stage },
1102:           measures: ['accuracy', 'response_time'],
1103:         };
1104:     }
1105:   }
