1141:   /**
1142:    * Evaluate the player's response using the module's drive probes.
1143:    * Determines which drive was selected by option label keywords and scores accordingly.
1144:    */
1145:   private evaluateViaDriveProbes(
1146:     module: StageAssessment,
1147:     responseText: string,
1148:   ): {
1149:     passed: boolean;
1150:     polarityDirection: 'sto' | 'sts' | 'neutral';
1151:     driveScores: { agency: number; communion: number; eros: number; agape: number };
1152:     driveSignals: { agency: string; communion: string; eros: string; agape: string };
1153:     feedback: string;
1154:   } {
1155:     const lower = responseText.toLowerCase();
1156: 
1157:     // Determine which drive the player expressed based on option label keywords
1158:     // The options presented are: 'act with agency', 'seek connection', 'reach higher', 'return to foundation'
1159:     const selectedDrive: 'agency' | 'communion' | 'eros' | 'agape' | null =
1160:       lower.includes('agency') ? 'agency' :
1161:       lower.includes('connection') ? 'communion' :
1162:       lower.includes('higher') ? 'eros' :
1163:       lower.includes('foundation') ? 'agape' :
1164:       null;
1165: 
1166:     // D.9: Use shared shadow keyword detection helper (DRY)
1167:     const shadowMatch = AgenticOrchestrator.detectShadowKeywords(responseText);
1168:     const hasShadowAddiction = shadowMatch?.quadrant === 'DarkAddiction';
1169:     const hasShadowAversion = shadowMatch?.quadrant === 'DarkAllergy';
1170:     const hasGoldenAddiction = shadowMatch?.quadrant === 'GoldenAddiction';
1171:     const hasGoldenAllergy = shadowMatch?.quadrant === 'GoldenAllergy';
1172: 
1173:     function scoreDrive(drive: 'agency' | 'communion' | 'eros' | 'agape'): { signal: string; score: number } {
1174:       if (selectedDrive === drive) {
1175:         // The selected drive: check for shadow signals
1176:         if (hasShadowAddiction && (drive === 'agency' || drive === 'eros')) {
1177:           return { signal: 'DarkAddicted', score: 0.3 };
1178:         }
1179:         if (hasShadowAversion && (drive === 'communion' || drive === 'agape')) {
1180:           return { signal: 'DarkAverted', score: 0.3 };
1181:         }
1182:         if (hasGoldenAddiction && drive === 'eros') {
1183:           return { signal: 'GoldenAddicted', score: 0.3 };
1184:         }
1185:         if (hasGoldenAllergy && drive === 'agape') {
1186:           return { signal: 'GoldenAverted', score: 0.3 };
1187:         }
1188:         return { signal: 'HealthyBalanced', score: 0.8 };
1189:       }
1190:       // Non-selected drives: baseline neutral
1191:       // BUT: if selectedDrive is null (write-in that doesn't match any option label),
1192:       // AND the text contains shadow keywords, apply shadow signal to prevent false altitude shifts
1193:       if (selectedDrive === null) {
1194:         if (hasShadowAddiction && (drive === 'agency' || drive === 'eros')) {
1195:           return { signal: 'DarkAddicted', score: 0.3 };
1196:         }
1197:         if (hasShadowAversion && (drive === 'communion' || drive === 'agape')) {
1198:           return { signal: 'DarkAverted', score: 0.3 };
1199:         }
1200:         if (hasGoldenAddiction && drive === 'eros') {
1201:           return { signal: 'GoldenAddicted', score: 0.3 };
1202:         }
1203:         if (hasGoldenAllergy && drive === 'agape') {
1204:           return { signal: 'GoldenAverted', score: 0.3 };
1205:         }
1206:       }
1207:       return { signal: 'HealthyBalanced', score: 0.5 };
1208:     }
1209: 
1210:     const agencyResult = scoreDrive('agency');
1211:     const communionResult = scoreDrive('communion');
1212:     const erosResult = scoreDrive('eros');
1213:     const agapeResult = scoreDrive('agape');
1214: 
1215:     const agencyScore = agencyResult.score;
1216:     const communionScore = communionResult.score;
1217:     const erosScore = erosResult.score;
1218:     const agapeScore = agapeResult.score;
1219: 
1220:     // STS: agency+eros dominate communion+agape
1221:     // STO: communion+agape dominate
1222:     // Neutral: balanced
1223:     const selfDominant = agencyScore + erosScore;
1224:     const otherDominant = communionScore + agapeScore;
1225:     let polarityDirection: 'sto' | 'sts' | 'neutral';
1226:     if (selfDominant > otherDominant + 0.3) polarityDirection = 'sts';
1227:     else if (otherDominant > selfDominant + 0.3) polarityDirection = 'sto';
1228:     else polarityDirection = 'neutral';
1229: 
1230:     // Determine pass/fail from rubric threshold
1231:     // If write-in is present, boost scores based on semantic depth heuristics
1232:     const wordCount = lower.split(/\s+/).filter(w => w.length > 0).length;
1233:     const uniqueWords = new Set(lower.split(/\s+/).filter(w => w.length > 0)).size;
1234:     const conceptDensity = wordCount > 0 ? uniqueWords / wordCount : 0;
1235: 
1236:     // Compute semantic depth bonus from write-in quality
1237:     // Length bonus: responses >20 words get depth bonus
1238:     const lengthBonus = wordCount > 20 ? Math.min(0.15, wordCount * 0.003) : 0;
1239:     // Concept density bonus: >60% unique words indicates conceptual richness
1240:     const densityBonus = conceptDensity > 0.6 ? 0.1 : (conceptDensity > 0.4 ? 0.05 : 0);
1241:     // Shadow awareness bonus: acknowledging shadow patterns indicates integration
1242:     const shadowAware = lower.includes('shadow') || lower.includes('pattern') || lower.includes('growth') || lower.includes('heal');
1243:     const awarenessBonus = shadowAware ? 0.1 : 0;
1244:     const semanticBonus = lengthBonus + densityBonus + awarenessBonus;
1245: 
1246:     // Apply semantic bonus to all scores (caps at 1.0)
1247:     const adjustedAgencyScore = Math.min(1.0, agencyScore + (selectedDrive === 'agency' ? semanticBonus : 0));
1248:     const adjustedCommunionScore = Math.min(1.0, communionScore + (selectedDrive === 'communion' ? semanticBonus : 0));
1249:     const adjustedErosScore = Math.min(1.0, erosScore + (selectedDrive === 'eros' ? semanticBonus : 0));
1250:     const adjustedAgapeScore = Math.min(1.0, agapeScore + (selectedDrive === 'agape' ? semanticBonus : 0));
1251: 
1252:     const avgScore = (adjustedAgencyScore + adjustedCommunionScore + adjustedErosScore + adjustedAgapeScore) / 4;
1253:     const passThreshold = module.scoringRubric.passThreshold ?? 0.5;
1254:     const passed = avgScore >= passThreshold;
1255: 
1256:     // Build feedback with depth-adjusted scores
1257:     const depthNote = semanticBonus > 0
1258:       ? ` (${wordCount} words, ${(conceptDensity * 100).toFixed(0)}% unique, +${(semanticBonus * 100).toFixed(0)}% depth)`
1259:       : '';
1260:     const feedback = passed
1261:       ? `Your response demonstrated balanced engagement with the ${module.line} ${module.stage} challenge. Agency: ${(adjustedAgencyScore * 100).toFixed(0)}%, Communion: ${(adjustedCommunionScore * 100).toFixed(0)}%, Eros: ${(adjustedErosScore * 100).toFixed(0)}%, Agape: ${(adjustedAgapeScore * 100).toFixed(0)}%.${depthNote}`
1262:       : `The challenge revealed areas for growth. Your ${module.line} ${module.stage} response showed room for deeper integration.`;
1263: 
1264:     return {
1265:       passed,
1266:       polarityDirection,
1267:       driveScores: { agency: adjustedAgencyScore, communion: adjustedCommunionScore, eros: adjustedErosScore, agape: adjustedAgapeScore },
1268:       driveSignals: {
1269:         agency: agencyResult.signal,
1270:         communion: communionResult.signal,
1271:         eros: erosResult.signal,
1272:         agape: agapeResult.signal,
1273:       },
1274:       feedback,
1275:     };
1276:   }
