1297:   /**
1298:    * Compute an altitude shift signal when the player demonstrates consistent
1299:    * HealthyBalanced drive patterns across ALL 4 drives (selected drive must score
1300:    * healthy, not shadow).
1301:    * Returns a ConsequenceRecord-compatible object or null if no shift is warranted.
1302:    */
1303:   private computeAltitudeShift(
1304:     _driveSignals: { agency: string; communion: string; eros: string; agape: string },
1305:     module: StageAssessment,
1306:     currentEncounterStage: Stage,
1307:     passed: boolean,
1308:   ): { line: Line; from: Stage; to: Stage } | null {
1309:     const key = module.line;
1310: 
1311:     if (!passed) {
1312:       return null; // Failures don't count but don't reset total count either
1313:     }
1314: 
1315:     // Use TOTAL passes per line (not consecutive) — the scheduler alternates lines
1316:     // so consecutive passes are mathematically impossible with 8+ lines.
1317:     // Threshold of 2 passes: demonstrates sustained capacity on the same line.
1318:     const totalPasses = (this._consecutivePasses.get(key) ?? 0) + 1;
1319:     this._consecutivePasses.set(key, totalPasses);
1320: 
1321:     if (totalPasses < 2) {
1322:       return null; // Need at least 2 passes on this line
1323:     }
1324: 
1325:     // Shift achieved — reset counter so future passes require 2 fresh wins
1326:     this._consecutivePasses.set(key, 0);
1327:     return { line: module.line, from: currentEncounterStage, to: currentEncounterStage };
1328:   }
